diffs.patch:
Index: index.html
===================================================================
--- index.html	
+++ index.html	
@@ -0,0 +1,424 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width, initial-scale=1.0">
+<title>WARZONE-OPS — Browser FPS (Original Fan-Inspired Prototype)</title>
+<meta name="description" content="Original browser first-person shooter inspired by battle-royale military shooters. All code and assets procedural/original.">
+<style>
+:root{
+  --bg:#0b0e12; --panel:rgba(10,14,18,.78); --panel2:rgba(16,22,28,.88);
+  --line:rgba(255,255,255,.12); --txt:#eef2f5; --dim:#9aa7b2;
+  --accent:#d8ff3e; --cyan:#39d5ff; --amber:#ffb224; --red:#ff3b30; --green:#37d67a;
+  --font:"Arial Narrow",Arial,Helvetica,sans-serif;
+}
+*{box-sizing:border-box;margin:0;padding:0}
+html,body{width:100%;height:100%;background:var(--bg);color:var(--txt);font-family:var(--font);overflow:hidden}
+#app{position:fixed;inset:0}
+canvas#game{position:absolute;inset:0;width:100%;height:100%;display:block}
+/* ---------- HUD ---------- */
+#hud{position:absolute;inset:0;pointer-events:none;display:none;z-index:5}
+#hud.on{display:block}
+.hud-plate{background:var(--panel);border:1px solid var(--line);border-radius:4px;backdrop-filter:blur(4px)}
+#minimap-wrap{position:absolute;top:14px;left:14px;width:196px;padding:8px}
+#minimap{display:block;width:180px;height:180px;border-radius:50%;border:2px solid rgba(255,255,255,.25);background:#10161b}
+#zone-status{margin-top:6px;font-size:12px;letter-spacing:.08em;color:var(--dim);text-transform:uppercase}
+#zone-status b{color:var(--txt)}
+#zone-status.danger b{color:var(--red)}
+#compass{position:absolute;top:14px;left:50%;transform:translateX(-50%);width:min(520px,60vw);padding:4px 12px 6px;text-align:center}
+#compass-deg{font-size:12px;color:var(--accent);letter-spacing:.2em}
+#compass-strip{position:relative;height:22px;overflow:hidden;font-size:13px;letter-spacing:.25em;color:var(--dim)}
+#compass-strip .tick{position:absolute;top:0;transform:translateX(-50%)}
+#compass-strip .card{color:var(--txt);font-weight:bold}
+#compass-poi{font-size:11px;color:var(--dim);letter-spacing:.15em;text-transform:uppercase}
+#topright{position:absolute;top:14px;right:14px;display:flex;gap:8px;align-items:stretch}
+.stat{padding:6px 12px;text-align:center;min-width:76px}
+.stat .v{font-size:22px;font-weight:800;line-height:1}
+.stat .k{font-size:10px;color:var(--dim);letter-spacing:.18em}
+#killfeed{position:absolute;top:120px;right:14px;display:flex;flex-direction:column;gap:4px;align-items:flex-end;max-width:340px}
+.feed{font-size:13px;padding:4px 10px;background:rgba(0,0,0,.62);border-right:3px solid var(--accent);border-radius:3px}
+.feed.me{border-right-color:var(--cyan)}
+.feed.enemy{border-right-color:var(--red)}
+#crosshair{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:24px;height:24px}
+#crosshair span{position:absolute;background:rgba(255,255,255,.9);box-shadow:0 0 3px #000}
+#crosshair .t{left:11px;top:0;width:2px;height:7px}#crosshair .b{left:11px;bottom:0;width:2px;height:7px}
+#crosshair .l{left:0;top:11px;width:7px;height:2px}#crosshair .r{right:0;top:11px;width:7px;height:2px}
+#crosshair .dot{left:11px;top:11px;width:2px;height:2px}
+#crosshair.ads span{opacity:.35}
+#hitmarker{position:absolute;left:50%;top:50%;width:28px;height:28px;transform:translate(-50%,-50%) rotate(45deg);opacity:0}
+#hitmarker span{position:absolute;background:#fff}
+#hitmarker .h{left:0;right:0;top:13px;height:2px}#hitmarker .v{top:0;bottom:0;left:13px;width:2px}
+#hitmarker.show{animation:hit .25s ease-out}
+#hitmarker.kill span{background:var(--red)}
+@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) rotate(45deg) scale(1.3)}100%{opacity:0;transform:translate(-50%,-50%) rotate(45deg) scale(.9)}}
+#dmg-vignette{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 55%,rgba(255,30,20,.55) 100%)}
+#heal-vignette{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 60%,rgba(55,214,122,.35) 100%)}
+#dmg-dir{position:absolute;left:50%;top:50%;width:120px;height:120px;transform:translate(-50%,-50%);opacity:0}
+#bottom-left{position:absolute;left:14px;bottom:14px;padding:10px 14px;min-width:250px}
+#hp-row{display:flex;align-items:center;gap:10px}
+#hp-num{font-size:34px;font-weight:800}
+#hp-bar{flex:1;height:10px;background:rgba(255,255,255,.12);border-radius:5px;overflow:hidden}
+#hp-fill{height:100%;width:100%;background:linear-gradient(90deg,#e8f4ff,#fff)}
+#armor-row{display:flex;gap:5px;margin-top:7px;align-items:center}
+.plate{width:64px;height:10px;border:1px solid rgba(255,255,255,.35);border-radius:2px;background:rgba(255,255,255,.06)}
+.plate.full{background:var(--cyan);box-shadow:0 0 6px rgba(57,213,255,.7)}
+#plate-hint{font-size:11px;color:var(--dim);margin-left:6px;letter-spacing:.06em}
+#bottom-right{position:absolute;right:14px;bottom:14px;padding:10px 14px;text-align:right;min-width:250px}
+#weapon-name{font-size:13px;letter-spacing:.2em;color:var(--accent);text-transform:uppercase}
+#ammo{font-size:38px;font-weight:800;line-height:1}
+#ammo .res{font-size:18px;color:var(--dim);font-weight:400}
+#fire-mode{font-size:11px;color:var(--dim);letter-spacing:.2em}
+#slots{display:flex;gap:6px;justify-content:flex-end;margin-top:6px;font-size:11px;color:var(--dim)}
+.slot{border:1px solid var(--line);padding:2px 8px;border-radius:3px}
+.slot.ready{color:var(--accent);border-color:var(--accent)}
+#reload-tip{font-size:13px;color:var(--amber);letter-spacing:.15em;display:none;margin-top:4px}
+#obj-banner{position:absolute;top:76px;left:50%;transform:translateX(-50%);font-size:13px;letter-spacing:.12em;padding:6px 16px;text-transform:uppercase;white-space:nowrap}
+#obj-banner b{color:var(--accent)}
+#toast{position:absolute;bottom:150px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;gap:6px;align-items:center}
+.toast-msg{background:rgba(0,0,0,.7);border:1px solid var(--line);padding:6px 16px;border-radius:4px;font-size:14px;letter-spacing:.08em}
+#interact{position:absolute;left:50%;top:58%;transform:translateX(-50%);font-size:14px;background:rgba(0,0,0,.65);padding:6px 14px;border:1px solid var(--accent);border-radius:4px;display:none;color:var(--accent)}
+/* ---------- Screens ---------- */
+.screen{position:absolute;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 30%,rgba(40,60,70,.92),rgba(5,8,10,.96)),repeating-linear-gradient(0deg,rgba(255,255,255,.015) 0 2px,transparent 2px 4px)}
+.screen.hidden{display:none}
+.card{width:min(860px,94vw);max-height:94vh;overflow:auto;background:var(--panel2);border:1px solid rgba(216,255,62,.25);border-radius:8px;padding:28px 32px;box-shadow:0 20px 80px rgba(0,0,0,.6)}
+.kicker{font-size:12px;letter-spacing:.35em;color:var(--accent);text-transform:uppercase}
+h1{font-size:clamp(34px,6vw,58px);letter-spacing:.04em;line-height:.95;margin:6px 0 4px;font-weight:900}
+h1 .thin{font-weight:300;color:var(--dim)}
+.sub{color:var(--dim);font-size:14px;letter-spacing:.06em;margin-bottom:14px}
+.loadouts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}
+.loadout{border:1px solid var(--line);border-radius:6px;padding:12px;cursor:pointer;background:rgba(255,255,255,.03);pointer-events:auto}
+.loadout:hover{border-color:var(--accent)}
+.loadout.sel{border-color:var(--accent);background:rgba(216,255,62,.08);box-shadow:0 0 0 1px var(--accent)}
+.loadout h3{font-size:16px;letter-spacing:.12em}
+.loadout p{font-size:12px;color:var(--dim);margin-top:4px;line-height:1.5}
+.loadout .statline{font-size:12px;color:var(--cyan);margin-top:6px}
+.controls-grid{display:grid;grid-template-columns:1fr 1fr;gap:4px 18px;font-size:13px;color:var(--dim);margin:10px 0}
+.controls-grid b{color:var(--txt);font-weight:700;background:rgba(255,255,255,.08);border:1px solid var(--line);border-radius:3px;padding:0 6px;margin-right:6px;font-size:12px}
+.btn{pointer-events:auto;cursor:pointer;border:0;border-radius:4px;font-family:var(--font);font-weight:800;letter-spacing:.2em;padding:14px 26px;font-size:16px}
+.btn-go{background:var(--accent);color:#10140a}
+.btn-go:hover{filter:brightness(1.1)}
+.btn-ghost{background:transparent;color:var(--txt);border:1px solid var(--line);font-size:13px;padding:10px 16px}
+.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:12px}
+label.opt{font-size:13px;color:var(--dim);display:flex;gap:8px;align-items:center;pointer-events:auto}
+.legal{font-size:11px;color:var(--dim);margin-top:12px;line-height:1.6}
+#end-title.win{color:var(--accent)} #end-title.lose{color:var(--red)}
+#end-stats{display:flex;gap:18px;margin:12px 0;font-size:14px}
+#end-stats b{font-size:28px;display:block}
+#err{position:absolute;z-index:99;left:50%;bottom:8px;transform:translateX(-50%);font-size:12px;color:#ffb0a8;background:rgba(60,0,0,.8);padding:4px 12px;border-radius:4px;display:none}
+#fps{position:absolute;left:14px;top:206px;font-size:11px;color:var(--dim);letter-spacing:.1em}
+@media (max-width:760px){.loadouts{grid-template-columns:1fr}#minimap-wrap{transform:scale(.8);transform-origin:top left}.controls-grid{grid-template-columns:1fr}}
+</style>
+<script type="importmap">{"imports":{"three":"https://unpkg.com/three@0.160.0/build/three.module.js"}}</script>
+</head>
+<body>
+<div id="app">
+<canvas id="game"></canvas>
+<div id="hud" aria-label="Game HUD">
+  <div id="minimap-wrap" class="hud-plate"><canvas id="minimap" width="180" height="180"></canvas><div id="zone-status">CIRCLE <b id="zone-timer">--</b> · <b id="zone-phase">STABLE</b></div></div>
+  <div id="compass" class="hud-plate"><div id="compass-deg">0</div><div id="compass-strip"></div><div id="compass-poi">OUTPOST “DUSTLINE” · ORIGINAL MAP</div></div>
+  <div id="topright"><div class="stat hud-plate"><div class="v" id="st-hostile">8</div><div class="k">HOSTILE</div></div><div class="stat hud-plate"><div class="v" id="st-kills">0</div><div class="k">KILLS</div></div><div class="stat hud-plate"><div class="v" id="st-time">0:00</div><div class="k">TIME</div></div></div>
+  <div id="killfeed" aria-live="polite"></div>
+  <div id="obj-banner" class="hud-plate">ELIMINATE ALL HOSTILES · <b id="obj-count">8</b> REMAIN</div>
+  <div id="crosshair"><span class="t"></span><span class="b"></span><span class="l"></span><span class="r"></span><span class="dot"></span></div>
+  <div id="hitmarker"><span class="h"></span><span class="v"></span></div>
+  <div id="dmg-vignette"></div><div id="heal-vignette"></div>
+  <svg id="dmg-dir" viewBox="0 0 120 120"><path id="dmg-arc" d="M60 6 A54 54 0 0 1 100 25" stroke="rgba(255,60,40,.95)" stroke-width="9" fill="none" stroke-linecap="round"/></svg>
+  <div id="bottom-left" class="hud-plate"><div id="hp-row"><div id="hp-num">100</div><div id="hp-bar"><div id="hp-fill"></div></div></div><div id="armor-row"><div class="plate" id="pl0"></div><div class="plate" id="pl1"></div><div class="plate" id="pl2"></div><span id="plate-hint">[E] PLATE · [Q] UAV(3 KILLS)</span></div></div>
+  <div id="bottom-right" class="hud-plate"><div id="weapon-name">AR-7 “DUSTLINE”</div><div id="ammo"><span id="ammo-mag">30</span> <span class="res">/ <span id="ammo-res">120</span></span></div><div id="fire-mode">AUTO · [R] RELOAD · [RMB] ADS</div><div id="slots"><span class="slot" id="slot-uav">UAV ○</span><span class="slot" id="slot-plate">PLATES ×2</span></div><div id="reload-tip">RELOADING…</div></div>
+  <div id="toast"></div><div id="interact"></div>
+</div>
+<div id="fps"></div><div id="err" role="alert"></div>
+
+<!-- START -->
+<div class="screen" id="screen-start">
+  <div class="card">
+    <div class="kicker">Original browser FPS · solo drill</div>
+    <h1>WARZONE<span class="thin">-OPS</span></h1>
+    <div class="sub">Inspired by the <i>visual language</i> of battle-royale military shooters (HUD · loadout · shrinking circle · last-one-standing). 100% original code &amp; procedural assets — no proprietary files.</div>
+    <div class="kicker" style="font-size:11px">1 · Choose loadout</div>
+    <div class="loadouts" id="loadouts">
+      <div class="loadout sel" data-l="assault"><h3>ASSAULT</h3><p>Balanced auto rifle. Forgiving recoil, medium range.</p><div class="statline">DMG 26 · RPM 540 · MAG 30 · ADS 1.0×</div></div>
+      <div class="loadout" data-l="smg"><h3>CQB · SMG</h3><p>Fast fire, fast move. Built for containers &amp; alleys.</p><div class="statline">DMG 19 · RPM 800 · MAG 40 · ADS 0.9×</div></div>
+      <div class="loadout" data-l="scout"><h3>SCOUT</h3><p>Hard-hitting semi rifle. Punishes aim, rewards heads.</p><div class="statline">DMG 55 · RPM 220 · MAG 10 · ADS 1.6× zoom</div></div>
+    </div>
+    <div class="kicker" style="font-size:11px">2 · Controls (desktop)</div>
+    <div class="controls-grid">
+      <div><b>W A S D</b> move</div><div><b>MOUSE</b> look · <b>CLICK</b> infil (locks pointer)</div>
+      <div><b>LMB</b> fire · <b>RMB</b> aim (ADS)</div><div><b>R</b> reload · <b>SHIFT</b> sprint · <b>SPACE</b> jump</div>
+      <div><b>E / 4</b> armor plate · <b>Q</b> UAV (after 3 kills)</div><div><b>C</b> crouch · <b>P</b> pause · <b>H</b> help · <b>M</b> mute</div>
+    </div>
+    <div class="row">
+      <label class="opt">Sensitivity <input id="opt-sens" type="range" min="0.3" max="3" step="0.1" value="1" style="pointer-events:auto"></label>
+      <label class="opt"><input id="opt-flash" type="checkbox" style="pointer-events:auto"> reduce flash</label>
+      <label class="opt"><input id="opt-quality" type="checkbox" checked style="pointer-events:auto"> hi-quality shadows</label>
+    </div>
+    <div class="row"><button class="btn btn-go" id="btn-deploy">▶ &nbsp;INFIL — START MATCH</button><button class="btn btn-ghost" id="btn-help">HOW TO WIN</button></div>
+    <div class="legal">Objective: eliminate <b>8 hostile bots</b> and stay inside the shrinking safe circle. Kills: 3 → UAV sweep (red dots on minimap/tablet). Damage: armor absorbs first, health regens after 5 s out of fire. Lose: HP hits 0. Win: all hostiles down. References (informational only): callofduty.com/warzone, Warzone HUD guide videos, interfaceingame.com, gameuidatabase.com, CharlieIntel HUD articles, BO7 S03 blog. Shipped map, guns, names (“Dustline”, AR-7…) are original.</div>
+  </div>
+</div>
+
+<!-- PAUSE/HELP -->
+<div class="screen hidden" id="screen-pause"><div class="card" style="text-align:center"><div class="kicker">Paused — pointer released</div><h1>STAND BY</h1><div class="sub">Click RESUME to re-lock pointer. H toggles this panel.</div><div class="row" style="justify-content:center"><button class="btn btn-go" id="btn-resume">RESUME</button><button class="btn btn-ghost" id="btn-quit">ABANDON MATCH</button></div></div></div>
+
+<!-- END -->
+<div class="screen hidden" id="screen-end"><div class="card" style="text-align:center"><div class="kicker" id="end-kicker">After-action report</div><h1 id="end-title">VICTORY</h1><div class="sub" id="end-sub"></div><div id="end-stats"><div><b id="end-kills">0</b>KILLS</div><div><b id="end-time">0:00</b>TIME</div><div><b id="end-acc">0%</b>ACCURACY</div><div><b id="end-zone">1</b>ZONE PHASE</div></div><div class="row" style="justify-content:center"><button class="btn btn-go" id="btn-again">REDEPLOY (R)</button></div></div></div>
+</div>
+<script type="module">
+import * as THREE from 'three';
+const $=id=>document.getElementById(id);
+const err=m=>{const e=$('err');e.style.display='block';e.textContent=m;clearTimeout(e._t);e._t=setTimeout(()=>e.style.display='none',5000);};
+// ---------- Audio (procedural, no assets) ----------
+let AC=null,muted=false;
+function ac(){if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(AC&&AC.state==='suspended')AC.resume();return AC;}
+function noiseBuf(a,dur){const b=a.createBuffer(1,a.sampleRate*dur,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);return b;}
+function shot(kind){if(muted)return;const a=ac();if(!a)return;const t=a.currentTime;
+  const src=a.createBufferSource();src.buffer=noiseBuf(a,kind==='scout'?0.35:0.18);
+  const f=a.createBiquadFilter();f.type='lowpass';f.frequency.setValueAtTime(kind==='scout'?900:2400,t);f.frequency.exponentialRampToValueAtTime(220,t+0.15);
+  const g=a.createGain();g.gain.setValueAtTime(0.5,t);g.gain.exponentialRampToValueAtTime(0.001,t+(kind==='scout'?0.32:0.16));
+  src.connect(f);f.connect(g);g.connect(a.destination);src.start(t);
+  const o=a.createOscillator();o.type='square';o.frequency.setValueAtTime(kind==='scout'?110:160,t);o.frequency.exponentialRampToValueAtTime(40,t+0.1);
+  const g2=a.createGain();g2.gain.setValueAtTime(0.25,t);g2.gain.exponentialRampToValueAtTime(0.001,t+0.1);o.connect(g2);g2.connect(a.destination);o.start(t);o.stop(t+0.12);}
+function blip(fr=880,d=.07,v=.15){if(muted)return;const a=ac();if(!a)return;const t=a.currentTime;const o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=fr;g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+d+.02);}
+const sHit=()=>blip(1200,.06,.2),sKill=()=>{blip(700,.09,.25);setTimeout(()=>blip(1050,.12,.25),90);},sHurt=()=>blip(180,.2,.3),sReload=()=>{blip(500,.05,.15);setTimeout(()=>blip(750,.05,.15),180);},sZone=()=>blip(240,.4,.25),sWin=()=>{[523,659,784,1046].forEach((f,i)=>setTimeout(()=>blip(f,.18,.25),i*140));},sLose=()=>{[400,300,220,150].forEach((f,i)=>setTimeout(()=>blip(f,.2,.25),i*150));},sPlate=()=>blip(950,.1,.2),sUav=()=>blip(660,.15,.2);
+// ---------- Config / state ----------
+const LOADOUTS={assault:{name:'AR-7 “DUSTLINE”',dmg:26,rpm:540,mag:30,reserve:150,reload:2.0,spread:0.018,adsSpread:0.006,auto:true,zoom:50,move:6.2},
+smg:{name:'VK-9 “HORNET”',dmg:19,rpm:800,mag:40,reserve:200,reload:1.7,spread:0.028,adsSpread:0.011,auto:true,zoom:55,move:6.8},
+scout:{name:'LR-12 “LONGVIEW”',dmg:55,rpm:220,mag:10,reserve:50,reload:2.4,spread:0.03,adsSpread:0.002,auto:false,zoom:32,move:5.8}};
+let L=LOADOUTS.assault,loadoutKey='assault';
+const S={mode:'menu',hp:100,armor:0,plates:2,mag:30,reserve:120,kills:0,shots:0,hits:0,t0:0,zonePhase:0,uav:false,uavT:0,reloading:false,lastHurt:-99,ads:0,dead:false};
+const ZONES=[{r:58,wait:20},{r:44,wait:22},{r:30,wait:20},{r:18,wait:18},{r:8,wait:16},{r:2,wait:99}];
+// ---------- Three setup ----------
+let renderer,scene,camera,gunGroup,muzzle,ground;
+const canvas=$('game');
+try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});}catch(e){err('WebGL unavailable: '+e.message);throw e;}
+renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);
+renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
+scene=new THREE.Scene();scene.background=new THREE.Color(0x9db8c8);scene.fog=new THREE.Fog(0xc3cfd4,40,190);
+camera=new THREE.PerspectiveCamera(75,innerWidth/innerHeight,0.08,600);
+scene.add(new THREE.HemisphereLight(0xdfeaf2,0x5a5348,0.95));
+const sun=new THREE.DirectionalLight(0xfff2dd,1.9);sun.position.set(60,90,30);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-90;sun.shadow.camera.right=90;sun.shadow.camera.top=90;sun.shadow.camera.bottom=-90;sun.shadow.camera.far=300;scene.add(sun);
+// sky sun sprite + distant dunes
+{const g=new THREE.Mesh(new THREE.SphereGeometry(9,16,16),new THREE.MeshBasicMaterial({color:0xfff3cf,fog:false}));g.position.set(220,140,-260);scene.add(g);
+const duneMat=new THREE.MeshLambertMaterial({color:0xb99f78});
