// Browser verification: load page, assert HUD/screens, start match via
// pointer-lock-free path (call startMatch directly), simulate combat states,
// capture screenshots.
const { chromium } = require('playwright-core');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--autoplay-policy=no-user-gesture-required'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text().slice(0, 200)); });

  await page.goto('http://127.0.0.1:3000/index.html', { waitUntil: 'networkidle', timeout: 45000 });
  await page.waitForTimeout(4000);

  const has = async (id) => await page.evaluate((i) => !!document.getElementById(i), id);
  const results = {};
  for (const id of ['screen-start', 'hud', 'minimap', 'compass', 'killfeed', 'hitmarker',
    'ammo-mag', 'hp-num', 'zone-timer', 'btn-deploy', 'screen-end', 'screen-pause']) {
    results[id] = await has(id);
  }
  results.webgl = await page.evaluate(() => !!document.querySelector('#game'));
  results.gameHook = await page.evaluate(() => !!window.__game);
  console.log('DOM:', JSON.stringify(results));

  await page.screenshot({ path: 'screenshots/final-01-start.png' });

  // Start match programmatically (pointer lock unavailable headless).
  await page.evaluate(() => window.__game.startMatch());
  await page.waitForTimeout(2500);
  results.hudOn = await page.evaluate(() => document.getElementById('hud').classList.contains('on'));
  results.enemies = await page.evaluate(() => window.__game.enemies.length);
  console.log('MATCH:', JSON.stringify({ hudOn: results.hudOn, enemies: results.enemies }));
  await page.screenshot({ path: 'screenshots/final-02-combat.png' });

  // Combat: aim at first alive enemy and fire until a hit registers.
  const combat = await page.evaluate(() => {
    const g = window.__game;
    const e = g.enemies.find(x => x.alive);
    if (!e) return { ok: false };
    // teleport player in front of enemy, face it
    const ep = e.g.position;
    g.P.pos.set(ep.x + 4, 1.7, ep.z + 6);
    g.P.yaw = Math.atan2(-(ep.x - g.P.pos.x), -(ep.z - g.P.pos.z)) + Math.PI;
    // face via lookAt math: yaw such that camera faces enemy
    const dx = ep.x - g.P.pos.x, dz = ep.z - g.P.pos.z;
    g.P.yaw = Math.atan2(-dx, -dz);
    return { ok: true, hp: e.hp };
  });
  // Fire several shots (shoot uses raycast from camera; ensure camera transform updated)
  await page.waitForTimeout(300);
  await page.evaluate(() => { const g = window.__game; g.S.mag = 30; for (let i = 0; i < 12; i++) { try { g.shoot(); } catch (e) {} } });
  await page.waitForTimeout(800);
  const after = await page.evaluate(() => {
    const g = window.__game;
    return { shots: g.S.shots, hits: g.S.hits, mag: g.S.mag, kills: g.S.kills };
  });
  console.log('COMBAT:', JSON.stringify({ ...combat, ...after }));
  await page.screenshot({ path: 'screenshots/final-03-firing.png' });

  // Damage state: hurt player, check vignette + HP drop.
  const hpBefore = await page.evaluate(() => window.__game.S.hp);
  await page.evaluate(() => window.__game.S.hp = 100);
  await page.evaluate(() => {
    const g = window.__game;
    const e = g.enemies.find(x => x.alive);
    // call internal hurt via enemy damage path simulation: damageEnemy on enemy + hurtPlayer
    g.enemies[0] && null;
  });
  // Use exposed hurtPlayer indirectly: teleport enemy next to player and let AI shoot
  await page.evaluate(() => {
    const g = window.__game;
