  await page.evaluate(() => { window.__game.S.mag = 0; window.__game.startReload(); });
  await page.waitForTimeout(500);
  const rel = await page.evaluate(() => ({ reloading: window.__game.S.reloading, tip: document.getElementById('reload-tip').style.display }));
