// Focused combat-accuracy test: freeze a bot dead-ahead, fire spaced shots.
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text().slice(0, 160)); });
  await page.goto('http://127.0.0.1:3000/index.html', { waitUntil: 'networkidle', timeout: 45000 });
  await page.waitForTimeout(3500);
  await page.evaluate(() => window.__game.startMatch());
  await page.waitForTimeout(1000);
  // Freeze bot 8m dead ahead of camera, ADS to tighten spread, spaced shots.
  await page.evaluate(() => {
    const g = window.__game;
    const e = g.enemies.find(x => x.alive);
    window.__t = e;
    const yaw = g.P.yaw;
    const fx = -Math.sin(yaw), fz = -Math.cos(yaw);
    e.g.position.set(g.P.pos.x + fx * 8, 0, g.P.pos.z + fz * 8);
    e.tx = e.g.position.x; e.tz = e.g.position.z; e.state = 'patrol'; e.shootT = 99;
    g.S.mag = 30;
  });
  for (let i = 0; i < 10; i++) {
    await page.evaluate(() => { try { window.__game.shoot(); } catch (e) {} });
    await page.waitForTimeout(150); // respect 540rpm throttle
  }
  await page.waitForTimeout(500);
  const r = await page.evaluate(() => ({
    shots: window.__game.S.shots, hits: window.__game.S.hits,
    enemyHp: Math.round(window.__t.hp), kills: window.__game.S.kills,
    feed: document.getElementById('killfeed').children.length,
  }));
  console.log('AIMED-FIRE:', JSON.stringify(r));
  await page.screenshot({ path: 'screenshots/final-03-firing.png' });
  console.log('ERRORS:', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

