    e.g.position.set(g.P.pos.x + fx * 8, 0, g.P.pos.z + fz * 8);
    e.tx = e.g.position.x; e.tz = e.g.position.z; e.state = 'patrol'; e.shootT = 99;
    return new Promise(res => setTimeout(() => {
      // replicate shoot ray exactly (zero spread) using three from page? use camera math
      const out = {};
