// Raycast autopsy: report exactly what the shot ray hits.
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('pageerror:', e.message));
  await page.goto('http://127.0.0.1:3000/index.html', { waitUntil: 'networkidle', timeout: 45000 });
  await page.waitForTimeout(3500);
  await page.evaluate(() => window.__game.startMatch());
  await page.waitForTimeout(1000);
  const r = await page.evaluate(() => {
    const g = window.__game;
    const e = g.enemies.find(x => x.alive);
    const yaw = g.P.yaw;
    e.g.position.set(g.P.pos.x + (-Math.sin(yaw)) * 8, 0, g.P.pos.z + (-Math.cos(yaw)) * 8);
    e.tx = e.g.position.x; e.tz = e.g.position.z; e.state = 'patrol'; e.shootT = 99;
    g.camera.rotation.x = -0.03;
    return new Promise(res => setTimeout(() => {
      g.ray.setFromCamera({ x: 0, y: 0 }, g.camera);
      const dir = g.ray.ray.direction;
      const org = g.ray.ray.origin;
      const hitsE = [];
      for (const en of g.enemies) {
        if (!en.alive) continue;
        const h1 = g.ray.intersectObject(en.g.children[1], false)[0];
        const h0 = g.ray.intersectObject(en.g.children[0], false)[0];
        if (h1 || h0) hitsE.push({ d: +((h1 || h0).distance).toFixed(2), head: !!h1 });
      }
      const wall = g.ray.intersectObjects(g.obstacles.children, true)[0];
      res({
        origin: { x: +org.x.toFixed(2), y: +org.y.toFixed(2), z: +org.z.toFixed(2) },
        dir: { x: +dir.x.toFixed(3), y: +dir.y.toFixed(3), z: +dir.z.toFixed(3) },
        enemyPos: { x: +e.g.position.x.toFixed(2), z: +e.g.position.z.toFixed(2) },
        enemyHits: hitsE,
        wall: wall ? { d: +wall.distance.toFixed(2), geo: wall.object.geometry.type, pos: { x: +wall.object.position.x.toFixed(1), y: +wall.object.position.y.toFixed(1), z: +wall.object.position.z.toFixed(1) } } : null,
      });
    }, 700));
  });
  console.log(JSON.stringify(r, null, 1));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

