// Final capture against the PUBLIC deployment.
const { chromium } = require('playwright-core');
const BASE = 'https://timothy-ctrl-lifetime-hydrocodone.trycloudflare.com/index.html';
(async () => {
  const browser = await chromium.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    args: ['--no-sandbox', '--use-gl=swiftshader', '--enable-unsafe-swiftshader'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text().slice(0, 160)); });
  await page.goto(BASE, { waitUntil: 'networkidle', timeout: 90000 });
  await page.waitForTimeout(5000);
  const dom = await page.evaluate(() => ({ start: !!document.getElementById('screen-start'), hook: !!window.__game }));
  console.log('PUBLIC DOM:', JSON.stringify(dom));
  await page.screenshot({ path: 'screenshots/final-01-start.png' });

  await page.evaluate(() => window.__game.startMatch());
  await page.waitForTimeout(2500);
  await page.screenshot({ path: 'screenshots/final-02-combat.png' });

  // enemy dead-ahead, fire one aimed shot
  const fire = await page.evaluate(() => {
    const g = window.__game;
    const e = g.enemies.find(x => x.alive);
    const yaw = g.P.yaw;
    e.g.position.set(g.P.pos.x + (-Math.sin(yaw)) * 10, 0, g.P.pos.z + (-Math.cos(yaw)) * 10);
    e.tx = e.g.position.x; e.tz = e.g.position.z; e.state = 'patrol'; e.shootT = 99;
    e.g.updateMatrixWorld(true);
    g.camera.rotation.x = -0.05; g.S.kick = 0; g.S.mag = 30;
    try { g.shoot(); } catch (err) { return { err: String(err) }; }
    return { shots: g.S.shots, hits: g.S.hits };
  });
  await page.waitForTimeout(400);
  console.log('PUBLIC FIRE:', JSON.stringify(fire));
  await page.screenshot({ path: 'screenshots/final-03-firing.png' });

  // let enemy AI engage for damage state
  await page.evaluate(() => {
    const g = window.__game;
    const e = g.enemies.find(x => x.alive);
    if (e) { e.g.position.set(g.P.pos.x + 3, 0, g.P.pos.z + 3); e.shootT = 0.05; e.state = 'combat'; }
  });
  await page.waitForTimeout(2500);
  const dmg = await page.evaluate(() => ({ hp: Math.round(window.__game.S.hp * 10) / 10 }));
  console.log('PUBLIC DAMAGE:', JSON.stringify(dmg));
  await page.screenshot({ path: 'screenshots/final-04-damage.png' });

  // victory
  await page.evaluate(() => {
    const g = window.__game;
    for (const e of g.enemies) { if (e.alive) e.alive = false; }
    g.S.kills = 8; g.endGame(true);
  });
  await page.waitForTimeout(800);
  await page.screenshot({ path: 'screenshots/final-05-victory.png' });

  // restart
  await page.evaluate(() => window.__game.restart());
  await page.waitForTimeout(1500);
  const re = await page.evaluate(() => ({ mode: window.__game.S.mode, alive: window.__game.enemies.filter(e => e.alive).length }));
  console.log('PUBLIC RESTART:', JSON.stringify(re));
  await page.screenshot({ path: 'screenshots/final-06-restarted.png' });

  // defeat
  await page.evaluate(() => { const g = window.__game; g.S.hp = 0; g.S.armor = 0; g.endGame(false); });
  await page.waitForTimeout(600);
  await page.screenshot({ path: 'screenshots/final-07-defeat.png' });

  console.log('ERRORS:', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });
